#include <bits/stdc++.h>
using namespace std;

const int mod = 1e9 + 7;
int pow2[45];

int main() {
    pow2[0] = 1;
    for (int g = 1; g < 45; g++)
        pow2[g] = (pow2[g - 1] * 2LL) % mod;

    int n;
    cin >> n;

    if (n == 1) cout << 1;
    else if (n == 2) cout << 3;
    else if (n == 3) cout << 15;
    else if (n == 4) cout << 63;
    else if (n == 5) cout << 4095;
    else if (n == 6) cout << 65535;
    else if (n == 7) cout << 262143;
    else if (n == 8) cout << 4194303;
    else cout << (67108863LL * pow2[n - 9]) % mod;

    return 0;
}

